?><div class="mb-8"><p class="mb-2 text-sm font-semibold text-blue-600">Controle de acesso</p><h2 class="text-3xl font-extrabold">Validador de carteirinha</h2><p class="mt-2 text-sm text-slate-500">Aponte a câmara para o QR Code do associado.</p></div><div class="grid gap-6 lg:grid-cols-5"><section class="shadow-soft rounded-2xl border border-slate-100 bg-white p-6 lg:col-span-3"><div id="reader" class="mx-auto max-w-lg overflow-hidden rounded-xl"></div><div class="mt-5 flex items-center gap-3 rounded-lg bg-blue-50 p-4 text-sm text-blue-800"><span class="text-xl">⌁</span><p><b>Posicione o QR Code dentro da moldura.</b><br><span class="text-xs">A validação acontece automaticamente.</span></p></div></section><section id="result" class="shadow-soft rounded-2xl border border-slate-100 bg-white p-7 lg:col-span-2"><div class="flex h-full min-h-[330px] flex-col items-center justify-center text-center"><div id="resultIcon" class="mb-5 grid h-20 w-20 place-items-center rounded-full bg-slate-100 text-4xl text-slate-400">⌁</div><h3 id="resultTitle" class="text-xl font-bold">Aguardando leitura</h3><p id="resultText" class="mt-2 text-sm text-slate-400">O resultado da validação aparecerá aqui.</p><div id="resultData" class="mt-6 hidden w-full rounded-xl bg-slate-50 p-4 text-left text-sm"></div></div></section></div><script src="https://unpkg.com/html5-qrcode"></script><script>const icon=document.getElementById('resultIcon'),title=document.getElementById('resultTitle'),text=document.getElementById('resultText'),data=document.getElementById('resultData');let locked=false;function show(x){locked=false;const status=x.status_financeiro||'';const ok=status==='EM_DIA',warn=status==='DEVEDOR';icon.className='mb-5 grid h-20 w-20 place-items-center rounded-full text-4xl '+(ok?'bg-emerald-100 text-emerald-600':warn?'bg-amber-100 text-amber-600':'bg-red-100 text-red-600');icon.textContent=ok?'✓':warn?'!':'×';title.className='text-xl font-bold '+(ok?'text-emerald-700':warn?'text-amber-700':'text-red-700');title.textContent=ok?'ASSOCIADO EM DIA':warn?'ASSOCIADO DEVEDOR':'ACESSO NEGADO';text.textContent=ok?'Acesso liberado.':warn?'Existe uma pendência financeira.':'Carteirinha inválida ou associado desfiliado.';data.innerHTML=x.nome?'<b>'+x.nome+'</b><br><span class="text-slate-500">Matrícula: '+x.matricula+'</span>':'QR Code não reconhecido';data.classList.remove('hidden');}function scanSuccess(url){if(locked)return;locked=true;fetch(url).then(r=>r.json()).then(show).catch(()=>show({status_financeiro:'DESFILIADO'}));setTimeout(()=>locked=false,5000)}new Html5QrcodeScanner('reader',{fps:10,qrbox:{width:250,height:250},rememberLastUsedCamera:true},false).render(scanSuccess,()=>{});</script><?php admin_end();